+    super();
+    throw new java.lang.UnsupportedOperationException("This is a utility class and cannot be instantiated");
+  }
+}
PATCH
ant test.compile > build/utilityclass-compile.log 2>&1 && ant test.javacCurrent > build/utilityclass-baseline.log 2>&1; result=$?; tail -12 build/utilityclass-compile.log; grep -n -A 30 -B 4 -E 'UtilityClassGeneric|NullPointerException|FAIL|BUILD (FAILED|SUCCESSFUL)' build/utilityclass-baseline.log | tail -110; exit "$result"

